const listAuditEventRows = `-- name: ListAuditEventRows :many
SELECT id, chain_seq, stream_type, stream_id, event_type, operation_id, operation_class, actor_type, actor_id, actor_fingerprint, origin, origin_fingerprint, request_descriptor, authorization_outcome, authorization_detail, result, result_code, effect_outcome, changed_fields, before_ref, after_ref, before_flag, after_flag, before_count, after_count, evidence_kind, evidence_fingerprint, occurred_at
FROM audit_event_rows
WHERE (?1 = '' OR actor_id = ?1)
  AND (?2 = '' OR instr(lower(event_type), lower(?2)) > 0)
  AND occurred_at >= ?3
  AND occurred_at <= ?4
  AND (?5 = 0 OR chain_seq < ?5)
  AND (
      json_array_length(?6) = 0
      OR stream_type IN (
          SELECT CAST(value AS TEXT) FROM json_each(?6)
      )
  )
ORDER BY chain_seq DESC
LIMIT ?7
`

type ListAuditEventRowsParams struct {
	ActorID         interface{} `json:"actor_id"`
	EventType       interface{} `json:"event_type"`
	FilterFromTime  time.Time   `json:"filter_from_time"`
	FilterToTime    time.Time   `json:"filter_to_time"`
	BeforeSeq       interface{} `json:"before_seq"`
	StreamTypesJson interface{} `json:"stream_types_json"`
	RowLimit        int64       `json:"row_limit"`
}

// The retained AuditEvent wire shape represents each resource effect. An
// operation with no effects is still evidence (most importantly a rejected
// authentication attempt), so it contributes one operation-only row instead
// of disappearing from the API. Operation rows that do have effects are not
// duplicated in the result.
func (q *Queries) ListAuditEventRows(ctx context.Context, arg ListAuditEventRowsParams) ([]AuditEventRow, error) {
	rows, err := q.db.QueryContext(ctx, listAuditEventRows,
		arg.ActorID,
		arg.EventType,
		arg.FilterFromTime,
		arg.FilterToTime,
		arg.BeforeSeq,
		arg.StreamTypesJson,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AuditEventRow{}
	for rows.Next() {
		var i AuditEventRow
		if err := rows.Scan(
			&i.ID,
			&i.ChainSeq,
			&i.StreamType,
			&i.StreamID,
			&i.EventType,
			&i.OperationID,
			&i.OperationClass,
			&i.ActorType,
			&i.ActorID,
			&i.ActorFingerprint,
			&i.Origin,
			&i.OriginFingerprint,
			&i.RequestDescriptor,
			&i.AuthorizationOutcome,
			&i.AuthorizationDetail,
			&i.Result,
			&i.ResultCode,
			&i.EffectOutcome,
			&i.ChangedFields,
			&i.BeforeRef,
			&i.AfterRef,
			&i.BeforeFlag,
			&i.AfterFlag,
			&i.BeforeCount,
			&i.AfterCount,
			&i.EvidenceKind,
			&i.EvidenceFingerprint,
			&i.OccurredAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockAuditChainHead = `-- name: LockAuditChainHead :one

SELECT stream, head_hash, height
FROM audit_chain_head
WHERE stream = ?
`

type LockAuditChainHeadRow struct {
	Stream   string `json:"stream"`
	HeadHash []byte `json:"head_hash"`
	Height   int64  `json:"height"`
}

// The append-only audit chain.
//
// Every write here runs inside the transaction store.WithAudit opened,
// after LockAuditChainHead has serialised the appenders. There is no
// UPDATE or DELETE statement for the two chain tables in this file
// other than the sanctioned retention delete: the database rejects
// them anyway, and a query that exists is a query that gets called.
// Take the stream's head under a row lock and return the tip. Every
// appender starts here, which is what makes chain_seq gapless and the
// chain a total order under concurrency.
func (q *Queries) LockAuditChainHead(ctx context.Context, stream string) (LockAuditChainHeadRow, error) {
	row := q.db.QueryRowContext(ctx, lockAuditChainHead, stream)
	var i LockAuditChainHeadRow
	err := row.Scan(&i.Stream, &i.HeadHash, &i.Height)
	return i, err
}

const nextAuditEffectSeq = `-- name: NextAuditEffectSeq :one
SELECT CAST(COALESCE(MAX(effect_seq) + 1, 0) AS INTEGER)
FROM audit_effects
WHERE operation_id = ?
`

// The next position within an operation. Late effects continue the
// numbering the initial ones started.
func (q *Queries) NextAuditEffectSeq(ctx context.Context, operationID string) (int64, error) {
	row := q.db.QueryRowContext(ctx, nextAuditEffectSeq, operationID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}
